```js
class Array2 {
    constructor(items) {
        var ptr0 = isLikeNone(items) ? 0 : passArrayJsValueToWasm0(items, wasm.__wbindgen_malloc);
        var len0 = WASM_VECTOR_LEN;
        const ret = wasm.array_new(ptr0, len0);
        this.__wbg_ptr = ret >>> 0;
        ArrayFinalization.register(this, this.__wbg_ptr, this);   // ArrayFinalization doesn't exist, Array2Finalization should be used instead
        return this;
    }
