pub fn test_phrase_query_seek_backwards_safe() -> crate::Result<()> {
        let index = create_index(&["a b c", "a b c d"])?;
        let text_field = index.schema().get_field("text").unwrap();
        let searcher = index.reader()?.searcher();

        let terms: Vec<Term> = ["a", "b"]
            .iter()
            .map(|text| Term::from_field_text(text_field, text))
            .collect();
        let phrase_query = PhraseQuery::new(terms);
        let phrase_weight =
            phrase_query.phrase_weight(EnableScoring::disabled_from_schema(searcher.schema()))?;
        let mut scorer = phrase_weight.scorer(searcher.segment_reader(0), 1.0)?;

        // Initial doc is 0.
        assert_eq!(scorer.doc(), 0);

